IBurstAsyncWaiter::IBurstAsyncWaiter(
    IBurst* proxy) : proxy_(proxy) {}

IBurstAsyncWaiter::~IBurstAsyncWaiter() = default;

void IBurstAsyncWaiter::execute(
    android::nn::Request request, android::nn::MeasureTiming measure, absl::optional<android::nn::TimePoint> deadline, absl::optional<android::nn::Duration> loopTimeoutDuration, const std::vector<android::nn::TokenValuePair>& hints, const std::vector<android::nn::ExtensionNameAndPrefix>& extensionNameToPrefix, android::nn::ExecutionError* out_executionError, std::vector<android::nn::OutputShape>* out_outputShape, android::nn::Timing* out_timing) {
  base::RunLoop loop;
  proxy_->execute(std::move(request),std::move(measure),std::move(deadline),std::move(loopTimeoutDuration),std::move(hints),std::move(extensionNameToPrefix),
      base::BindOnce(
          [](base::RunLoop* loop,
             android::nn::ExecutionError* out_executionError
,
             std::vector<android::nn::OutputShape>* out_outputShape
,
             android::nn::Timing* out_timing
,
             android::nn::ExecutionError executionError,
             const std::vector<android::nn::OutputShape>& outputShape,
             android::nn::Timing timing) {*out_executionError = std::move(executionError);*out_outputShape = std::move(outputShape);*out_timing = std::move(timing);
            loop->Quit();
          },
          &loop,
          out_executionError,
          out_outputShape,
          out_timing));
  loop.Run();
}



void IBurstAsyncWaiter::createReusableExecution(
    android::nn::Request request, android::nn::MeasureTiming measure, absl::optional<android::nn::Duration> loopTimeoutDuration, const std::vector<android::nn::TokenValuePair>& hints, const std::vector<android::nn::ExtensionNameAndPrefix>& extensionNameToPrefix, android::nn::GeneralError* out_status, ::mojo::PendingRemote<::chromeos::nnapi::canonical::mojom::IExecution>* out_execution) {
  base::RunLoop loop;
  proxy_->createReusableExecution(std::move(request),std::move(measure),std::move(loopTimeoutDuration),std::move(hints),std::move(extensionNameToPrefix),
      base::BindOnce(
          [](base::RunLoop* loop,
             android::nn::GeneralError* out_status
,
             ::mojo::PendingRemote<::chromeos::nnapi::canonical::mojom::IExecution>* out_execution
,
             android::nn::GeneralError status,
             ::mojo::PendingRemote<::chromeos::nnapi::canonical::mojom::IExecution> execution) {*out_status = std::move(status);*out_execution = std::move(execution);
            loop->Quit();
          },
          &loop,
          out_status,
          out_execution));
  loop.Run();
}








